import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { environment } from '../../../environments/environment';
import { ToastService } from '../../core/services/toast.service';

@Component({
  selector: 'app-settings',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="page-container">
      <div class="page-header">
        <h1 class="page-title">// paramètres</h1>
        <p class="page-subtitle">Configuration de la plateforme DevSecOps IA</p>
      </div>

      <div style="display:flex;flex-direction:column;gap:16px;max-width:700px;">

        <!-- Connexions -->
        <div class="card">
          <div class="card-header"><span class="card-title">Connexions services</span></div>
          <div *ngFor="let s of services" class="service-row">
            <div class="service-icon" [style.color]="s.color" [style.background]="s.color+'11'">
              {{s.icon}}
            </div>
            <div style="flex:1;">
              <div class="service-name">{{s.name}}</div>
              <div class="service-url">{{s.url}}</div>
            </div>
            <div class="status-pill" [class.ok]="s.status === 'ok'" [class.err]="s.status === 'err'">
              <span>{{s.status === 'ok' ? '●' : '●'}}</span>
              {{s.status === 'ok' ? 'Connecté' : 'Hors ligne'}}
            </div>
          </div>
        </div>

        <!-- IA Config -->
        <div class="card">
          <div class="card-header"><span class="card-title">Configuration IA</span></div>
          <div class="form-group">
            <label class="form-label">Modèle Ollama</label>
            <input class="form-control" [value]="'llama3.2:3b'" readonly
                   style="font-family:var(--font-mono);color:var(--accent-blue);" />
          </div>
          <div class="form-group">
            <label class="form-label">Seuil de confiance Judge Agent</label>
            <div style="display:flex;align-items:center;gap:12px;">
              <input type="range" min="50" max="95" step="5" [(ngModel)]="confidenceThreshold"
                     style="flex:1;" />
              <span style="font-family:var(--font-mono);color:var(--accent-orange);min-width:40px;">
                {{confidenceThreshold}}%
              </span>
            </div>
            <div style="font-size:10px;color:var(--text-faint);margin-top:4px;">
              Seuil en dessous duquel le Judge refuse d'appliquer une correction automatiquement.
            </div>
          </div>
          <div class="form-group">
            <label class="form-label">URL Webhook n8n</label>
            <input class="form-control" [value]="n8nUrl" readonly
                   style="font-family:var(--font-mono);font-size:11px;" />
          </div>
          <button class="btn btn-primary btn-sm" (click)="saveConfig()">Sauvegarder</button>
        </div>

        <!-- Info plateforme -->
        <div class="card">
          <div class="card-header"><span class="card-title">Informations plateforme</span></div>
          <table style="width:100%;">
            <tr *ngFor="let info of platformInfo">
              <td style="font-size:11px;color:var(--text-faint);padding:7px 0;width:40%;">{{info.label}}</td>
              <td style="font-size:12px;color:var(--text-secondary);font-family:var(--font-mono);">{{info.value}}</td>
            </tr>
          </table>
        </div>

      </div>
    </div>
  `,
  styles: [`
    .service-row {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 12px 0;
      border-bottom: 1px solid var(--border);
      &:last-child { border-bottom: none; }
    }

    .service-icon {
      width: 34px; height: 34px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 16px;
      flex-shrink: 0;
    }

    .service-name {
      font-size: 13px;
      font-weight: 500;
      color: var(--text-primary);
    }

    .service-url {
      font-size: 10px;
      color: var(--text-faint);
      font-family: var(--font-mono);
    }

    .status-pill {
      font-size: 11px;
      padding: 4px 10px;
      border-radius: 20px;
      border: 1px solid var(--border);
      color: var(--text-muted);
      display: flex;
      align-items: center;
      gap: 4px;
      font-family: var(--font-mono);

      &.ok  { color: var(--accent-green); border-color: var(--accent-green); background: var(--accent-green-bg); }
      &.err { color: var(--accent-red);   border-color: var(--accent-red);   background: var(--accent-red-bg); }
    }
  `]
})
export class SettingsComponent {
  confidenceThreshold = 70;
  n8nUrl = `${environment.n8nUrl}/webhook/jenkins-event`;

  services = [
    { name: 'Jenkins',   icon: '⚙', color: '#f59e0b', url: 'http://172.31.172.61:8082', status: 'ok' },
    { name: 'SonarQube', icon: '◈', color: '#38bdf8', url: 'http://172.31.172.61:9000', status: 'ok' },
    { name: 'Ollama',    icon: '◆', color: '#22c55e', url: 'http://ollama:11434',        status: 'ok' },
    { name: 'n8n',       icon: '⬡', color: '#a78bfa', url: 'http://172.31.172.61:5678', status: 'ok' },
    { name: 'Nexus',     icon: '◧', color: '#e24b4a', url: 'http://172.31.172.61:8081', status: 'ok' },
    { name: 'GitHub',    icon: '◉', color: '#c8d8e8', url: 'github.com/souhaiel11/VermegPFE', status: 'ok' },
  ];

  platformInfo = [
    { label: 'Version Angular',    value: '17.x (Standalone)' },
    { label: 'Version Spring Boot', value: '3.1.5' },
    { label: 'Version n8n',         value: '2.14.2 (self-hosted)' },
    { label: 'Modèle LLM',          value: 'llama3.2:3b via Ollama' },
    { label: 'Base de données',      value: 'PostgreSQL 16' },
    { label: 'Environnement',        value: 'WSL Ubuntu 22.04' },
    { label: 'Auteur',               value: 'Amri Souhaiel — ESPRIT / Vermeg' },
  ];

  constructor(private toast: ToastService) {}

  saveConfig() {
    this.toast.success('Configuration sauvegardée', `Seuil Judge : ${this.confidenceThreshold}%`);
  }
}
